-- B16 (T082; the B16 check, decision 1, the owner's decision 2026-10-26 on the reviewer's advice;
-- ADR 0015 D3, Egypt PDPL). Generated by `prisma migrate diff --from-config-datasource --to-schema
-- prisma/schema --script` against a database holding every migration before it, then extended by
-- hand with rule 34.
--
-- What it lands: `verification_documents.erased_at`, set in an account deletion's transaction on
-- every document of the deleted person (the verification module's subscriber to the consequences
-- registry), and `storage_key_encrypted` made nullable, so the key can be cleared once the file is
-- removed after the commit. The rows stay: credentials and profiles point at them (ON DELETE
-- RESTRICT). A row whose key is still held after its erasure is retried by `erase-deleted-files`.

-- AlterTable
ALTER TABLE "verification_documents" ADD COLUMN     "erased_at" TIMESTAMPTZ(6),
ALTER COLUMN "storage_key_encrypted" DROP NOT NULL;

-- Hand-written: what the schema language cannot say (data-model.md §5, ERD §15).
-- Rule 34: a document loses its key only once it is erased, so a key never goes missing unseen.
ALTER TABLE "verification_documents" ADD CONSTRAINT "verification_documents_erased_key_check"
  CHECK ("storage_key_encrypted" IS NOT NULL OR "erased_at" IS NOT NULL);
